#!/bin/sh
# Assemble a U-Boot network-boot tree for the ARM SBC world (Rockchip, Allwinner, Amlogic, NXP i.MX/Layerscape, ...).
# U-Boot's distro/PXE boot DHCPs, TFTPs pxelinux.cfg/<...> (extlinux.conf syntax, generated by the server), and FDTDIR
# auto-selects the board's device tree via ${fdtfile}. The Debian arm64 kernel already ships hundreds of board DTBs, so
# ONE tree boots the whole U-Boot family - each board just needs its DTB present (it almost always is). The kernel/initrd
# are the KwickBoot arm64 Core, so a U-Boot SBC joins KwickBoot like any machine. SPDX-License-Identifier: AGPL-3.0-or-later
set -e
T=${KB_HOME:-$(cd "$(dirname "$0")/.." && pwd)}
CORE=${KB_CORE:-$T/http/kbcore-arm64}
OUT=${KB_OUT:-$T/tftp}
CHROOT=${KB_ARM64_CHROOT:-/var/tmp/kbcore-build-arm64/chroot}
[ -s "$CORE/vmlinuz" ] || { echo "no arm64 Core at $CORE (build it: KB_ARCH=arm64 build-core.sh)"; exit 1; }

mkdir -p "$OUT/uboot/dtbs"
echo ">>> arm64 Core kernel + initrd"
cp "$CORE/vmlinuz" "$OUT/uboot/vmlinuz"
cp "$CORE/initrd.img" "$OUT/uboot/initrd.img"

echo ">>> DTB library (every arm64 board device tree the Debian kernel ships)"
KV=$(ls "$CHROOT/lib/modules" 2>/dev/null | sort -V | tail -1)
DTBROOT="$CHROOT/usr/lib/linux-image-$KV"
if [ -d "$DTBROOT" ]; then
  # keep vendor subdirs (rockchip/ allwinner/ amlogic/ freescale/ qcom/ ...) so U-Boot's ${fdtfile} path resolves under FDTDIR
  ( cd "$DTBROOT" && find . -name '*.dtb' ) | while read -r f; do
    mkdir -p "$OUT/uboot/dtbs/$(dirname "$f")"
    cp "$DTBROOT/$f" "$OUT/uboot/dtbs/$f"
  done
else
  echo "    (arm64 kernel chroot not found at $DTBROOT - no DTBs staged; a board without a DTB in U-Boot's env won't get an FDT)"
fi

echo "U-Boot boot tree in $OUT/uboot:"
echo "  kernel $(du -h "$OUT/uboot/vmlinuz" | cut -f1), initrd $(du -h "$OUT/uboot/initrd.img" | cut -f1)"
echo "  $(find "$OUT/uboot/dtbs" -name '*.dtb' 2>/dev/null | wc -l) board DTBs ($(du -sh "$OUT/uboot/dtbs" 2>/dev/null | cut -f1))"
echo "  vendors: $(ls "$OUT/uboot/dtbs" 2>/dev/null | tr '\n' ' ')"
echo "  (pxelinux.cfg/* is generated by pxeserver per request - not staged here)"
